package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsLabel string   // PIC X(20) len=20 = SPACES
var WsACount int64   // PIC 99 len=2 = 0
var WsTotalA int64   // PIC 999 len=3 = 0
var WsCount int64    // PIC 999 len=3 = 0

var partRecords []string
var partIndex int
var currentPartRec PartRec

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func formatPIC99(v int64) string {
	// low-order 2 digits, zero padded
	// keep semantics for negative just in case
	v = v % 100
	if v < 0 {
		v += 100
	}
	return fmt.Sprintf("%02d", v)
}

func formatPIC999(v int64) string {
	v = v % 1000
	if v < 0 {
		v += 1000
	}
	return fmt.Sprintf("%03d", v)
}

func delimitedBySpace(s string) string {
	if idx := strings.IndexByte(s, ' '); idx >= 0 {
		return s[:idx]
	}
	return s
}

func loadPartFile() {
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0
	partIndex = 0
	partRecords = nil

	f, err := os.Open("input.dat")
	if err != nil {
		// no file => no records, subsequent READ will set EOF
		return
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	// Increase buffer for long lines (default 64k is enough for 15 bytes)
	// but keep default.
	for scanner.Scan() {
		line := scanner.Text()
		// scanner strips trailing \r for CRLF already, but if file had \r not part of CRLF,
		// it would remain. We keep as is.
		partRecords = append(partRecords, line)
	}
	// ignore scanner.Err for now; if error, treat as EOF
}

func ReadPara() {
	if partIndex < len(partRecords) {
		line := partRecords[partIndex]
		partIndex++
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		lbPart := line[0:8]
		lbRegion := line[8:11]
		lbSerialStr := line[11:15]

		var lbSerial int64
		trimmed := strings.TrimSpace(lbSerialStr)
		if trimmed == "" {
			lbSerial = 0
		} else {
			// LB-SERIAL is 9(4) digits only; parse as integer
			// if it contains non-digits, treat as 0
			isDigits := true
			for _, ch := range trimmed {
				if ch < '0' || ch > '9' {
					isDigits = false
					break
				}
			}
			if isDigits {
				var v int64
				for _, ch := range trimmed {
					v = v*10 + int64(ch-'0')
				}
				lbSerial = v
			} else {
				lbSerial = 0
			}
		}
		// store truncation for 9(4): keep low 4 digits
		lbSerial = lbSerial % 10000
		if lbSerial < 0 {
			lbSerial += 10000
		}
		currentPartRec = PartRec{
			LbPart:   lbPart,
			LbRegion: lbRegion,
			LbSerial: lbSerial,
		}
		WsEofFlag = "N"
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	WsACount = int64(strings.Count(currentPartRec.LbPart, "A"))
	// store truncation PIC 99
	WsACount = WsACount % 100
	if WsACount < 0 {
		WsACount += 100
	}

	// STRING ...
	piece1 := delimitedBySpace(currentPartRec.LbRegion)
	piece2 := "-"
	piece3 := delimitedBySpace(currentPartRec.LbPart)
	piece4 := "-"
	serialStr := fmt.Sprintf("%04d", currentPartRec.LbSerial)
	piece5 := serialStr

	pieces := []string{piece1, piece2, piece3, piece4, piece5}
	buf := make([]byte, 20)
	for i := range buf {
		buf[i] = ' '
	}
	pos := 0
	for _, p := range pieces {
		for i := 0; i < len(p); i++ {
			if pos < 20 {
				buf[pos] = p[i]
				pos++
			} else {
				break
			}
		}
	}
	WsLabel = string(buf)

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA = WsTotalA + WsACount
	WsTotalA = WsTotalA % 1000
	if WsTotalA < 0 {
		WsTotalA += 1000
	}
	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	WsCount = WsCount % 1000
	if WsCount < 0 {
		WsCount += 1000
	}

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	line := WsLabel + " A=" + formatPIC99(WsACount)
	fmt.Fprint(os.Stdout, line+"\n")

	// PERFORM READ-PARA
	ReadPara()
}

func SummaryPara() {
	line := "LABELS: " + formatPIC999(WsCount) + " A-TOTAL: " + formatPIC999(WsTotalA)
	fmt.Fprint(os.Stdout, line+"\n")
}

func MainPara() {
	// OPEN INPUT PART-FILE
	// already loaded in loadPartFile
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE PART-FILE
	SummaryPara()
}

func main() {
	loadPartFile()
	MainPara()
}
